  function errorsAllK(ord, inTr, kmax, y) { const out = []; let c = 0, s = 0; for (const j of ord) { if (!inTr[j]) continue; s += TR[j][2]; c++; if (c % 2 === 1) out.push((s / c > 0.5 ? 1 : 0) !== y ? 1 : 0); if (c >= kmax) break; } return out; }
  function shuffle(n, r) { const a = [...Array(n).keys()]; for (let i = n - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
  // Una estimación del error con el método m sobre los primeros n puntos.
  function estimate(m, n, k, r) {
