    const perm = shuffle(n, r);
    if (m === 'h30' || m === 'h50') {
      const nv = Math.round(n * (m === 'h30' ? 0.3 : 0.5)), val = perm.slice(0, nv), inTr = ALL.map(() => false);
      perm.slice(nv).forEach(j => { inTr[j] = true; });
      return val.filter(i => vote(ORD[i], inTr, k) !== TR[i][2]).length / nv;
    }
    const Kf = m === 'k5' ? 5 : 10, fold = Array(N).fill(-1); perm.forEach((j, p) => { fold[j] = p % Kf; });
    let e = 0;
    for (let f = 0; f < Kf; f++) { const inTr = ALL.map(j => j < n && fold[j] !== f); for (let i = 0; i < n; i++) if (fold[i] === f) e += vote(ORD[i], inTr, k) !== TR[i][2] ? 1 : 0; }
