  let seed = 1;
  const methSeg = K.segmented($('#val-method'), render);
  const NAMES = { h30: 'Holdout 30 %', h50: 'Holdout 50 %', k5: '5 pliegues', k10: '10 pliegues', loo: 'LOOCV' };

  function render() {
    const m = methSeg.get(), k = +$('#val-k').value, n = +$('#val-n').value, R = 200;
    $('#val-k-v').textContent = k; $('#val-n-v').textContent = n;
    const inAll = ALL.map(j => j < n);
    const trueErr = TE.filter((p, t) => vote(TORD[t], inAll, k) !== p[2]).length / TE.length;
    const summary = {};
