      for (let i = 0; i < reps; i++) est.push(estimate(mm, n, k, r));
      summary[mm] = { est, mean: K.mean(est), sd: est.length > 1 ? K.sd(est, 1) : 0 };
    });
    const S = summary[m];
    $('#val-mean').textContent = K.fmt(S.mean, 3); $('#val-sd').textContent = K.fmt(S.sd, 3); $('#val-true').textContent = K.fmt(trueErr, 3);

    // Histograma.
    const B = 30, hi = 0.45, w = hi / B, cnt = Array(B).fill(0);
    S.est.forEach(v => { cnt[Math.min(B - 1, Math.floor(v / w))]++; });
    const top = Math.max(...cnt);
    const c = K.chart($('#val-hist'), { width: 380, height: 250, x: [0, hi], y: [0, top * 1.12], margin: { left: 44, bottom: 40 } });
    c.axes({ xTicks: 5, yTicks: 4, xLabel: 'error estimado', yLabel: m === 'loo' ? 'estimación única' : 'repeticiones', xFmt: v => K.fmt(v, 2), yFmt: v => K.fmt(v, 0) });
    cnt.forEach((v, i) => { if (v) c.rect(i * w, 0, (i + 1) * w, v, 's1').style.fillOpacity = 0.55; });
    c.line(S.mean, 0, S.mean, top * 1.08, 's2 line');
    c.line(trueErr, 0, trueErr, top * 1.08, 's3 line dash');

    // Curva de validación con 10 pliegues (una partición) frente al error de prueba.
    const kmax = Math.min(39, n - Math.ceil(n / 10) - 1), ks = []; for (let kk = 1; kk <= kmax; kk += 2) ks.push(kk);
    const r = K.rng(seed * 104729 + n), perm = shuffle(n, r), fold = Array(N).fill(-1); perm.forEach((j, p) => { fold[j] = p % 10; });
    const foldErr = Array.from({ length: 10 }, () => Array(ks.length).fill(0)), foldN = Array(10).fill(0);
    for (let f = 0; f < 10; f++) { const inTr = ALL.map(j => j < n && fold[j] !== f);
