    const te = ks.map(kk => TE.filter((p, t) => vote(TORD[t], inAll, kk) !== p[2]).length / TE.length);
    let qb = 0; cv.forEach((v, q) => { if (v < cv[qb] - 1e-12) qb = q; });
    let q1 = qb; for (let q = ks.length - 1; q >= 0; q--) { if (cv[q] <= cv[qb] + se[qb] + 1e-12) { q1 = q; break; } }
