    const cc = K.chart($('#val-curve'), { width: 380, height: 250, x: [0, kmax + 1], y: [0, ymax], margin: { left: 44, bottom: 40 } });
    cc.axes({ xTicks: 5, yTicks: 5, xLabel: 'k (vecinos)', yLabel: 'error', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 2) });
    const band = ks.map((kk, q) => [kk, cv[q] + se[q]]).concat(ks.map((kk, q) => [kk, cv[q] - se[q]]).reverse());
    K.el('path', { d: 'M' + band.map(p => `${cc.X(p[0]).toFixed(1)},${cc.Y(p[1]).toFixed(1)}`).join('L') + 'Z', class: 's1 soft' }, cc.g).style.stroke = 'none';
    cc.path(ks.map((kk, q) => [kk, te[q]]), 's4 line dash');
    cc.path(ks.map((kk, q) => [kk, cv[q]]), 's1 line');
    cc.dot(ks[q1], cv[q1], 6, 's3 dot');
    cc.dot(ks[qb], cv[qb], 6, 's2 dot');
    $('#val-kcv').textContent = `${ks[qb]} (prueba ${K.fmt(te[qb], 3)})`;

    $('#val-tab').innerHTML = '<table class="plab-table"><thead><tr><th>Método</th><th>Modelos entrenados</th><th>Promedio</th><th>Desv. est.</th><th>Sesgo vs. prueba</th></tr></thead><tbody>' +
      Object.entries(NAMES).map(([mm, nm]) => { const s = summary[mm], fits = mm === 'loo' ? n : mm === 'k5' ? 5 * R : mm === 'k10' ? 10 * R : R;
        return `<tr${mm === m ? ' class="hl"' : ''}><td>${nm}</td><td>${fits}</td><td>${K.fmt(s.mean, 3)}</td><td>${K.fmt(s.sd, 3)}</td><td>${s.mean - trueErr >= 0 ? '+' : ''}${K.fmt(s.mean - trueErr, 3)}</td></tr>`; }).join('') +
      '</tbody></table><p class="plab-sub" style="margin:.4rem 0 0">Holdout y K pliegues: 200 repeticiones con particiones aleatorias. LOOCV es determinista. «Sesgo vs. prueba» compara el promedio con el error en los 400 puntos de prueba.</p>';

    const note = $('#val-note'), sdH = summary.h30.sd, sdK = summary.k10.sd;
    note.className = 'plab-note ' + (m.startsWith('h') ? 'warn' : 'good');
    note.textContent = (m.startsWith('h')
      ? `Con ${NAMES[m]} una sola estimación puede caer en cualquier lugar del histograma: su desviación estándar es ${K.fmt(S.sd, 3)}, frente a ${K.fmt(sdK, 3)} de 10 pliegues. `
      : `Con ${NAMES[m]} cada punto se valida una vez; la dispersión es ${K.fmt(S.sd, 3)} frente a ${K.fmt(sdH, 3)} del holdout 30 %. `) +
      `La validación cruzada elige k = ${ks[qb]} (la regla de un error estándar, k = ${ks[q1]}); su error en prueba es ${K.fmt(te[qb], 3)}, frente al mínimo de ${K.fmt(Math.min(...te), 3)} que solo se conocería haciendo trampa.`;
  }
  root.querySelectorAll('input[type=range]').forEach(el => el.addEventListener('input', render));
  $('#val-seed').addEventListener('click', () => { seed++; render(); });
  render();
})();
