### Varianza de las estimaciones

Con los datos del laboratorio comparamos la dispersión del holdout y de la validación cruzada repitiendo cada método con 200 semillas.

::: {#fig-val-varianza .cell execution_count=2}
``` {.python .cell-code}
import plotly.graph_objects as go
from sklearn.model_selection import train_test_split, KFold

def prob_clase1(X):
    return 1 / (1 + np.exp(-1.6 * (X[:, 1] - 5 - 2 * np.sin(0.8 * X[:, 0]))))

def generar(n, semilla):
    rng = np.random.default_rng(semilla)
    X = rng.uniform(0, 10, size=(n, 2)).round(2)
    return X, (rng.uniform(size=n) < prob_clase1(X)).astype(int)

X_big, y_big = generar(120, 1)
X_test, y_test = generar(400, 2)
knn5 = KNeighborsClassifier(n_neighbors=5, algorithm="brute")
error_real = 1 - knn5.fit(X_big, y_big).score(X_test, y_test)

holdout, kfold = [], []
for s in range(200):
    Xa, Xb, ya, yb = train_test_split(X_big, y_big, test_size=0.3, random_state=s)
    holdout.append(1 - knn5.fit(Xa, ya).score(Xb, yb))
    kfold.append(1 - cross_val_score(knn5, X_big, y_big, cv=KFold(10, shuffle=True, random_state=s)).mean())
loo = 1 - cross_val_score(knn5, X_big, y_big, cv=LeaveOneOut()).mean()

fig = go.Figure()
fig.add_trace(go.Histogram(x=holdout, name=f"holdout 30 % (desv. {np.std(holdout, ddof=1):.3f})", opacity=0.6, marker_color="#ea580c", xbins=dict(size=0.015)))
fig.add_trace(go.Histogram(x=kfold, name=f"10 pliegues (desv. {np.std(kfold, ddof=1):.3f})", opacity=0.6, marker_color="#2563eb", xbins=dict(size=0.015)))
fig.add_vline(x=error_real, line=dict(color="#16a34a", dash="dash"), annotation_text=f"prueba: {error_real:.3f}")
fig.update_layout(barmode="overlay", xaxis_title="error estimado", yaxis_title="repeticiones", height=360,
                  margin=dict(l=10, r=10, t=20, b=40), legend=dict(x=0.55, y=0.95))
fig.show()
print(f"LOOCV (determinista): {loo:.3f}")
```

