### Curva de validación y curva de aprendizaje

Una **curva de validación** grafica el error de entrenamiento y de validación cruzada contra un hiperparámetro; una **curva de aprendizaje**, contra el tamaño del entrenamiento. La primera diagnostica la complejidad; la segunda responde si conviene conseguir más datos: si las dos curvas ya convergieron, más datos no ayudarán; si siguen separadas, sí.

::: {.cell execution_count=3}
``` {.python .cell-code}
from plotly.subplots import make_subplots
from sklearn.model_selection import validation_curve, learning_curve, StratifiedKFold

cv10 = StratifiedKFold(10, shuffle=True, random_state=0)
ks = np.arange(1, 40, 2)
tr_sc, va_sc = validation_curve(KNeighborsClassifier(algorithm="brute"), X_big, y_big,
                                param_name="n_neighbors", param_range=ks, cv=cv10)
X_all, y_all = np.vstack([X_big, X_test]), np.concatenate([y_big, y_test])
tamanos, tr_lc, va_lc = learning_curve(KNeighborsClassifier(15), X_all, y_all, cv=cv10,
                                       train_sizes=np.linspace(0.1, 1.0, 8), shuffle=True, random_state=0)

fig = make_subplots(rows=1, cols=2, subplot_titles=("Curva de validación (k-NN)", "Curva de aprendizaje (15-NN)"))
for col, x, a, b in [(1, ks, tr_sc, va_sc), (2, tamanos, tr_lc, va_lc)]:
    fig.add_trace(go.Scatter(x=x, y=1 - a.mean(1), name="entrenamiento", line=dict(color="#2563eb"), showlegend=col == 1), row=1, col=col)
    fig.add_trace(go.Scatter(x=x, y=1 - b.mean(1), name="validación cruzada", line=dict(color="#7c3aed"),
                             error_y=dict(type="data", array=b.std(1) / np.sqrt(10)), showlegend=col == 1), row=1, col=col)
fig.update_xaxes(title_text="k", row=1, col=1); fig.update_xaxes(title_text="tamaño del entrenamiento", row=1, col=2)
fig.update_yaxes(title_text="error", row=1, col=1)
fig.update_layout(height=380, margin=dict(l=10, r=10, t=40, b=40), legend=dict(orientation="h", y=-0.25))
fig.show()
```

